import { comp, solid, text, par, seq, at } from "@still-shift/motion";
import { fontAsset } from "@still-shift/motion/node";

const font = await fontAsset(
  "plex-semibold",
  "/Users/jjae/Documents/playground/still-shift/assets/story-motion/fonts/plex-sans-semibold.ttf",
  { weight: "600" },
);

export default comp(
  { width: 640, height: 360, fps: 24, seconds: 4, assets: [font] },
  (c) => {
    const left = c.add(
      solid("left-gate", { size: [62, 126], color: "#E77D37" })
        .at(289, 195).anchor("center")
        .with({ startFrame: 0 }),
    );
    const right = c.add(
      solid("right-gate", { size: [62, 126], color: "#E77D37" })
        .at(351, 195).anchor("center")
        .with({ startFrame: 0 }),
    );
    const heading = c.add(
      text("Room to move", {
        fontAsset: font.id,
        fontSize: 36,
        color: "#1C3556",
      })
        .at(320, 76).anchor("center")
        .opacity(0)
        .with({ startFrame: 30 }),
    );
    c.add(solid("blue-square", { size: [108, 108], color: "#2464B4" }).at(320, 195).anchor("center"));
    c.add(solid("background", { size: [640, 360], color: "#F4F1E8" }).at(320, 180).anchor("center"));
    c.marker("open", 12, { label: "Make room" });
    c.marker("read", 48, { label: "Stillness for reading" });
    c.marker("farewell", 78, { label: "Heading fades" });
    // startFrame offsets the heading animation: local 12/18/48/60 => global 42/48/78/90.
    c.marker("heading-fade-local", 48, { label: "Local heading fade cue" });
    c.timeline(
      at("cue:open", par(
        left.x.from(289).to(212, { seconds: 0.75 }),
        right.x.from(351).to(428, { seconds: 0.75 }),
      )),
      at("cue:open", par(
        heading.alpha.from(0).to(1, { seconds: 0.25 }),
        heading.y.from(86).to(76, { seconds: 0.25 }),
      )),
      at("cue:heading-fade-local", heading.alpha.from(1).to(0, { seconds: 0.5 })),
    );
  },
);

