import { comp, solid, text, par, at } from "@still-shift/motion";
import { fontAsset } from "@still-shift/motion/node";

const font = await fontAsset(
  "room-heading-font",
  "/Users/jjae/Documents/playground/still-shift/assets/story-motion/fonts/plex-sans-semibold.ttf",
  { weight: "600" },
);

export default comp(
  {
    width: 640,
    height: 360,
    fps: 24,
    seconds: 4,
    background: "#F6F1E8",
    assets: [font],
  },
  (c) => {
    const heading = c.add(
      text("Room to move", {
        fontAsset: font.id,
        fontSize: 42,
        color: "#233849",
      })
        .at(320, 88)
        .anchor("center")
        .opacity(0)
        .with({ inPoint: 36, outPoint: 90 }),
    );
    const leftGate = c.add(
      solid("left-gate", { size: [52, 104], color: "#E67A3D" })
        .at(294, 225)
        .anchor("center")
        .with({ inPoint: 0, outPoint: 96 }),
    );
    const rightGate = c.add(
      solid("right-gate", { size: [52, 104], color: "#E67A3D" })
        .at(346, 225)
        .anchor("center")
        .with({ inPoint: 0, outPoint: 96 }),
    );
    c.add(
      solid("blue-square", { size: [104, 104], color: "#3975D4" })
        .at(320, 225)
        .anchor("center")
        .with({ inPoint: 0, outPoint: 96 }),
    );

    c.marker("open", 12, { label: "The gates make room" });
    c.marker("title", 36, { label: "Heading arrives" });
    c.marker("read", 48, { label: "Hold completely still to read" });
    c.marker("fade", 78, { label: "Heading fades" });
    c.marker("quiet", 90, { label: "Quiet final image" });

    c.timeline(
      at(
        "cue:open",
        par(
          leftGate.x.from(294).to(188, { seconds: 0.75 }),
          rightGate.x.from(346).to(452, { seconds: 0.75 }),
        ),
      ),
      at(
        "cue:title",
        par(
          heading.alpha.from(0).to(1, 12),
          heading.y.from(88).to(76, 12),
        ),
      ),
      at("cue:fade", heading.alpha.from(1).to(0, 12)),
    );
  },
);
